import Foundation
import Glibc

func fail(_ message: String) -> Never {
    FileHandle.standardError.write(Data((message + "\n").utf8))
    exit(1)
}
let arguments = CommandLine.arguments
if arguments.count < 3 { fail("usage: process-resource OUTPUT EXECUTABLE [ARGUMENTS]") }
let argumentStrings = arguments.dropFirst(2).map { strdup($0)! }
let environmentStrings = ProcessInfo.processInfo.environment.map { strdup("\($0.key)=\($0.value)")! }
defer {
    for value in argumentStrings { free(value) }
    for value in environmentStrings { free(value) }
}
var childArguments: [UnsafeMutablePointer<CChar>?] = argumentStrings.map { $0 } + [nil]
var childEnvironment: [UnsafeMutablePointer<CChar>?] = environmentStrings.map { $0 } + [nil]
var child: pid_t = 0
let started = DispatchTime.now().uptimeNanoseconds
let spawned = childArguments.withUnsafeMutableBufferPointer { argv in
    childEnvironment.withUnsafeMutableBufferPointer { env in
        posix_spawn(&child, argv[0]!, nil, nil, argv.baseAddress!, env.baseAddress!)
    }
}
if spawned != 0 { fail("posix_spawn failed: \(spawned)") }
var status: Int32 = 0
var usage = rusage()
var waited: pid_t
repeat { waited = wait4(child, &status, 0, &usage) } while waited == -1 && errno == EINTR
if waited != child { fail("wait4 failed: \(errno)") }
let finished = DispatchTime.now().uptimeNanoseconds
let metrics: [String: Any] = [
    "elapsed_seconds": Double(finished - started) / 1_000_000_000,
    "user_cpu_seconds": Double(usage.ru_utime.tv_sec) + Double(usage.ru_utime.tv_usec) / 1_000_000,
    "system_cpu_seconds": Double(usage.ru_stime.tv_sec) + Double(usage.ru_stime.tv_usec) / 1_000_000,
    "peak_rss_kib": usage.ru_maxrss,
    "minor_page_faults": usage.ru_minflt,
    "major_page_faults": usage.ru_majflt,
    "voluntary_context_switches": usage.ru_nvcsw,
    "involuntary_context_switches": usage.ru_nivcsw,
    "block_input_operations": usage.ru_inblock,
    "block_output_operations": usage.ru_oublock,
    "raw_wait_status": status,
]
try JSONSerialization.data(withJSONObject: metrics, options: [.prettyPrinted, .sortedKeys])
    .write(to: URL(fileURLWithPath: arguments[1]))
if status & 0x7f != 0 { exit(128 + (status & 0x7f)) }
exit((status >> 8) & 0xff)
